Section Build.
  Variables (ra sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (x8 x9 x16 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x29 x30 x31 : word).
  Variables (m : fmem) (TD WK : Z) (tl M1 : Z) (jt : list byte) (syms : list (option Z)).
  Variable POST : machine_state -> Prop.
  Hypothesis HTL : 1 <= tl <= 12.
  Hypothesis HM1 : 1 <= M1 <= 256.
  Hypothesis HJT : length jt = (4 * Z.to_nat (2^tl))%nat.
  Hypothesis HSL : length syms = Z.to_nat (2^tl).
  Hypothesis HTD : 0 < TD /\ TD + 4 * 2^tl <= 2^64.
  Hypothesis HWK : 0 < WK /\ WK + 2 * M1 <= 2^64.
  Hypothesis DTW : TD + 4 * 2^tl <= WK \/ WK + 2 * M1 <= TD.

  Definition bl_inv (m1 : fmem) (u : Z) (snext : list Z) (acc : list dcell) : Prop :=
    u8arr psegs m1 TD (concat (map fse_cell_bytes acc) ++ tsym (skipn (4 * Z.to_nat u) jt) (skipn (Z.to_nat u) syms))
    /\ u8arr psegs m1 WK (u16s (map (Z_to_bv 64) snext))
    /\ munch [(TD, TD + 4 * 2^tl); (WK, WK + 2 * M1)] m m1 /\ wmono psegs m m1 /\ mem_inv psegs m1.

  Notation ST pc mm x6 x7 x10 x28 :=
    (MS (mkR ra sp gp tp (Z_to_bv 64 16843009) x6 x7 x8 x9 x10 (Z_to_bv 64 (TD + 3 + 4 * 2^tl)) (Z_to_bv 64 (2^tl))
             (Z_to_bv 64 tl) (Z_to_bv 64 WK) (Z_to_bv 64 1431655765) (Z_to_bv 64 858993459) (Z_to_bv 64 252645135)
             x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
        F (Z_to_bv 64 pc) fc None mm (seg_rom psegs)).

  Lemma bl_loop : forall f u snext acc r m1 (x6 x7 x28 : word),
    build_loop tl f u syms snext acc = Ok r ->
    Z.of_nat f = 2^tl - u -> 0 <= u < 2^tl -> zlen acc = u -> zlen snext = M1 ->
    Forall (fun v => 0 <= v < 65536) snext ->
    bl_inv m1 u snext acc ->
    (forall m2 snext' (y6 y7 y10 y28 : word), zlen r = 2^tl -> bl_inv m2 (2^tl) snext' r ->
       evt psegs POST (ST 0x1bc14 m2 y6 y7 y10 y28)) ->
